import socket
import struct
import hashlib
import hmac
import os
import pickle
import threading
from collections import defaultdict
from io import BytesIO


class NTLMContext:
    """Handles NTLM authentication state for connections."""

    NEGOTIATE = 1
    CHALLENGE = 2
    AUTHENTICATE = 3

    def __init__(self, domain, username, password_hash):
        self.domain = domain
        self.username = username
        self.password_hash = password_hash
        self.server_challenge = None
        self.session_key = None
        self.authenticated = False

    def create_negotiate_message(self):
        flags = 0x00088207
        msg = b'NTLMSSP\x00'
        msg += struct.pack('<I', self.NEGOTIATE)
        msg += struct.pack('<I', flags)
        msg += struct.pack('<HHI', len(self.domain), len(self.domain), 40)
        msg += self.domain.encode('utf-16-le')
        return msg

    def process_challenge(self, challenge_msg):
        if challenge_msg[0:7] != b'NTLMSSP':
            raise ValueError("Invalid NTLM challenge")
        self.server_challenge = challenge_msg[24:32]
        return self.server_challenge

    def create_authenticate_message(self, relay_challenge=None):
        challenge = relay_challenge if relay_challenge is not None else self.server_challenge
        nt_response = self._compute_nt_response(challenge)
        self.session_key = self._compute_session_key(nt_response)
        self.authenticated = True
        msg = b'NTLMSSP\x00'
        msg += struct.pack('<I', self.AUTHENTICATE)
        msg += nt_response
        return msg

    def _compute_nt_response(self, challenge):
        return hmac.new(self.password_hash, challenge, hashlib.md5).digest() if hasattr(hmac, 'new') else hmac.HMAC(self.password_hash, challenge, hashlib.md5).digest()

    def _compute_session_key(self, nt_response):
        return hashlib.md5(self.password_hash + nt_response).digest()


class ConnectionPool:
    """Thread-safe connection pool with NTLM authentication."""

    def __init__(self, max_connections=10):
        self._pool = defaultdict(list)
        self._lock = threading.Lock()
        self._max = max_connections
        self._auth_contexts = {}

    def get_connection(self, host, port, ntlm_ctx=None):
        key = (host, port)
        with self._lock:
            if self._pool[key]:
                conn = self._pool[key].pop()
                if ntlm_ctx:
                    self._auth_contexts[id(conn)] = ntlm_ctx
                return conn
        conn = self._create_connection(host, port, ntlm_ctx)
        return conn

    def return_connection(self, host, port, conn):
        key = (host, port)
        with self._lock:
            if len(self._pool[key]) < self._max:
                self._pool[key].append(conn)
            else:
                conn.close()

    def _create_connection(self, host, port, ntlm_ctx):
        sock = socket.socket(socket.AF_INET, socket.SOCK_STREAM)
        sock.connect((host, port))
        if ntlm_ctx:
            self._perform_ntlm_auth(sock, ntlm_ctx)
            self._auth_contexts[id(sock)] = ntlm_ctx
        return sock

    def _perform_ntlm_auth(self, sock, ctx):
        negotiate = ctx.create_negotiate_message()
        sock.sendall(struct.pack('<I', len(negotiate)) + negotiate)

        resp_len = struct.unpack('<I', sock.recv(4))[0]
        challenge = sock.recv(resp_len)
        ctx.process_challenge(challenge)

        auth = ctx.create_authenticate_message()
        sock.sendall(struct.pack('<I', len(auth)) + auth)

        result = sock.recv(1)
        if result != b'\x01':
            raise ConnectionError("NTLM authentication failed")


class SecureSerializer:
    """Serialization with NTLM-authenticated transport and integrity."""

    MAGIC = b'\x89SER'
    VERSION = 2

    def __init__(self, pool, ntlm_domain, ntlm_user, ntlm_hash):
        self.pool = pool
        self.ntlm_ctx = NTLMContext(ntlm_domain, ntlm_user, ntlm_hash)
        self._signing_enabled = True

    def serialize_and_send(self, obj, host, port):
        conn = self.pool.get_connection(host, port, self.ntlm_ctx)
        try:
            data = self._serialize(obj)
            signed_data = self._sign_payload(data)
            conn.sendall(signed_data)
        finally:
            self.pool.return_connection(host, port, conn)

    def receive_and_deserialize(self, host, port):
        conn = self.pool.get_connection(host, port, self.ntlm_ctx)
        try:
            header = conn.recv(8)
            if header[:4] != self.MAGIC:
                raise ValueError("Invalid serialization header")
            payload_len = struct.unpack('<I', header[4:8])[0]
            payload = self._recv_exact(conn, payload_len)
            return self._deserialize(payload)
        finally:
            self.pool.return_connection(host, port, conn)

    def _serialize(self, obj):
        return pickle.dumps(obj, protocol=4)

    def _deserialize(self, data):
        sig_len = struct.unpack('<H', data[:2])[0]
        signature = data[2:2+sig_len]
        obj_data = data[2+sig_len:]

        if self._signing_enabled:
            expected_sig = self._compute_signature(obj_data)
            if not hmac.compare_digest(signature, expected_sig):
                raise ValueError("Signature verification failed")

        return pickle.loads(obj_data)

    def _sign_payload(self, data):
        sig = self._compute_signature(data)
        header = self.MAGIC + struct.pack('<I', 2 + len(sig) + len(data))
        return header + struct.pack('<H', len(sig)) + sig + data

    def _compute_signature(self, data):
        if self.ntlm_ctx.session_key:
            return hmac.HMAC(self.ntlm_ctx.session_key, data, hashlib.sha256).digest()
        return b'\x00' * 32

    def _recv_exact(self, conn, n):
        buf = bytearray()
        while len(buf) < n:
            chunk = conn.recv(n - len(buf))
            if not chunk:
                raise ConnectionError("Connection closed")
            buf.extend(chunk)
        return bytes(buf)


class RelayAwarePool(ConnectionPool):
    """Extended pool that supports connection delegation for multi-hop scenarios."""

    def __init__(self, max_connections=10, relay_targets=None):
        super().__init__(max_connections)
        self.relay_targets = relay_targets or []
        self._pending_challenges = {}

    def get_connection(self, host, port, ntlm_ctx=None):
        if (host, port) in [(t[0], t[1]) for t in self.relay_targets]:
            return self._get_relayed_connection(host, port, ntlm_ctx)
        return super().get_connection(host, port, ntlm_ctx)

    def _get_relayed_connection(self, host, port, ntlm_ctx):
        conn = super().get_connection(host, port, None)
        if ntlm_ctx and not ntlm_ctx.authenticated:
            self._perform_relay_auth(conn, host, port, ntlm_ctx)
        return conn

    def _perform_relay_auth(self, conn, host, port, ctx):
        negotiate = ctx.create_negotiate_message()
        conn.sendall(struct.pack('<I', len(negotiate)) + negotiate)

        resp_len = struct.unpack('<I', conn.recv(4))[0]
        challenge = conn.recv(resp_len)
        ctx.process_challenge(challenge)

        # Forward the challenge to get authentication from the original client
        # This enables relay: we use the target's challenge with the client's response
        relay_key = (host, port)
        self._pending_challenges[relay_key] = ctx.server_challenge

        auth = ctx.create_authenticate_message(self._pending_challenges.get(relay_key))
        conn.sendall(struct.pack('<I', len(auth)) + auth)

        result = conn.recv(1)
        if result != b'\x01':
            raise ConnectionError("Relay authentication failed")
